    (N'INV_CHECK',    N'INV',  N'Kiểm kho',                 N'FrmKiemKho',        4),
    (N'INV_WARN',     N'INV',  N'Cảnh báo tồn thấp',        N'FrmCanhBaoTon',     5),
    (N'INV_SUPPLIER', N'INV',  N'Nhà cung cấp',             N'FrmNhaCungCap',     6),
    (N'INV_EQUIP',    N'INV',  N'Thiết bị',                 N'FrmThietBi',        7),
