    (N'BM01',  69000), (N'BM02', 129000), (N'BM03',  30000), (N'BM04',  35000), (N'BM05',  39000),
    (N'BM06',  35000), (N'BM07',  39000), (N'BM08',  45000), (N'BM09',  42000), (N'BM10',  45000),
