    (N'BM16',  69000), (N'BM17', 139000), (N'BM18',  89000), (N'BM19',  99000), (N'BM20', 149000),
    (N'BM21',  99000), (N'BM22',  79000), (N'BM23',  85000), (N'BM24', 145000), (N'BM25',  65000),
    (N'BM26',  55000), (N'BM27',  25000), (N'BM28',  35000), (N'BM29',  28000), (N'BM30',  35000),
    (N'DU01',  20000), (N'DU02',  25000), (N'DU03',  25000), (N'DU04',  25000), (N'DU05',  15000),
    (N'DU06',  15000), (N'DU07',  15000), (N'DU08',  15000), (N'DU09',  15000), (N'DU10',  15000),
