/*------------------------------------------------------------------------------
  17. COMBO - CHI TIẾT (combo gồm những món nào)
      Bán 1 combo → trừ kho = công thức từng món thành phần x SoLuong
------------------------------------------------------------------------------*/
INSERT INTO dbo.Combo_ChiTiet (MaCombo, MaSanPham, SoLuong)
SELECT cb.MaSanPham, sp.MaSanPham, v.SoLuong
FROM (VALUES
    (N'CB01', N'BM01', 1), (N'CB01', N'DU01', 1),
    (N'CB02', N'BM03', 1), (N'CB02', N'DU03', 1),
    (N'CB03', N'BM12', 1), (N'CB03', N'DU02', 1),
    (N'CB04', N'BM18', 1), (N'CB04', N'DU04', 1),
    (N'CB05', N'BM22', 1), (N'CB05', N'DU05', 1),
    (N'CB06', N'BM01', 2), (N'CB06', N'DU01', 2)
) AS v (MaCombo, MaThanhPhan, SoLuong)
JOIN dbo.SanPham cb ON cb.MaSKU = v.MaCombo     AND cb.LoaiSanPham = N'Combo'
JOIN dbo.SanPham sp ON sp.MaSKU = v.MaThanhPhan AND sp.LoaiSanPham = N'ThanhPham';

IF (SELECT COUNT(*) FROM dbo.Combo_ChiTiet) <> 12
    THROW 50004, N'Combo_ChiTiet thiếu dòng: mã combo hoặc mã món gõ sai', 1;

/*------------------------------------------------------------------------------
  18. KHUYẾN MÃI (cửa hàng mở từ 01/09/2026)
      Món combo không áp thêm khuyến mãi; 1 hóa đơn tối đa 1 khuyến mãi
------------------------------------------------------------------------------*/
INSERT INTO dbo.KhuyenMai
    (MaCode, TenKhuyenMai, LoaiGiam, GiaTriGiam, GiamToiDa, DonToiThieu, MaChiNhanh, NgayBatDau, NgayKetThuc, DangHoatDong)
SELECT v.MaCode, v.TenKhuyenMai, v.LoaiGiam, v.GiaTriGiam, v.GiamToiDa, v.DonToiThieu,
       cn.MaChiNhanh, v.NgayBatDau, v.NgayKetThuc, 1
FROM (VALUES
    (N'KM-KHAITRUONG', N'Khai trương giảm 20% (tối đa 30.000đ)',     N'PhanTram', 20.00, 30000.00,      50000.00, NULL,
        CAST('2026-09-01 06:00:00' AS DATETIME2(0)), CAST('2026-09-07 21:00:00' AS DATETIME2(0))),
    (N'KM-GIAM10K',    N'Giảm 10.000đ cho hóa đơn từ 100.000đ',      N'SoTien',   10000.00, NULL,     100000.00, NULL,
        CAST('2026-09-08 06:00:00' AS DATETIME2(0)), CAST('2026-12-31 21:00:00' AS DATETIME2(0))),
    (N'KM-THUDUC15',   N'Tri ân khách Thủ Đức giảm 15% (tối đa 25.000đ)', N'PhanTram', 15.00, 25000.00, 80000.00, N'CN02',
        CAST('2026-09-15 06:00:00' AS DATETIME2(0)), CAST('2026-10-15 21:00:00' AS DATETIME2(0))),
    (N'KM-TRUNGTHU',   N'Trung thu giảm 10% (tối đa 20.000đ)',       N'PhanTram', 10.00, 20000.00,      60000.00, NULL,
        CAST('2026-09-20 06:00:00' AS DATETIME2(0)), CAST('2026-09-27 21:00:00' AS DATETIME2(0))),
    (N'KM-GOVAP-T10',  N'Tháng 10 Gò Vấp giảm 12.000đ cho hóa đơn từ 120.000đ', N'SoTien', 12000.00, NULL, 120000.00, N'CN03',
        CAST('2026-10-01 06:00:00' AS DATETIME2(0)), CAST('2026-10-31 21:00:00' AS DATETIME2(0)))
) AS v (MaCode, TenKhuyenMai, LoaiGiam, GiaTriGiam, GiamToiDa, DonToiThieu, MaChiNhanhCode, NgayBatDau, NgayKetThuc)
LEFT JOIN dbo.ChiNhanh cn ON cn.MaCode = v.MaChiNhanhCode;

IF EXISTS (SELECT 1 FROM dbo.KhuyenMai km
           WHERE km.MaChiNhanh IS NULL
             AND km.MaCode IN (N'KM-THUDUC15', N'KM-GOVAP-T10'))
