) AS v (TenNL, TenNCC, DonGia, MaChiNhanhCode, Dot1, Dot2, Dot3, Dot4)
CROSS APPLY (VALUES
    (CAST('2026-08-31' AS DATE), v.Dot1),
    (CAST('2026-09-08' AS DATE), v.Dot2),
    (CAST('2026-09-15' AS DATE), v.Dot3),
    (CAST('2026-09-22' AS DATE), v.Dot4)
) AS d (NgayNhan, SoLuong)
JOIN dbo.ChiNhanh       cn  ON cn.MaCode         = v.MaChiNhanhCode
JOIN dbo.NhaCungCap     ncc ON ncc.TenNCC        = v.TenNCC
JOIN dbo.NguyenLieu     nl  ON nl.TenNguyenLieu  = v.TenNL
JOIN dbo.Phieu_NhapHang pn  ON pn.MaChiNhanh     = cn.MaChiNhanh
                           AND pn.MaNCC          = ncc.MaNCC
                           AND pn.NgayNhan       = d.NgayNhan
WHERE d.SoLuong > 0;

IF (SELECT COUNT(*) FROM dbo.ChiTiet_NhapHang) <> 546
    THROW 50009, N'ChiTiet_NhapHang thiếu dòng: tên NL / NCC gõ sai hoặc NCC không giao đợt đó', 1;

IF EXISTS (SELECT 1 FROM dbo.Phieu_NhapHang pn
           WHERE NOT EXISTS (SELECT 1 FROM dbo.ChiTiet_NhapHang ct WHERE ct.MaPhieuNhap = pn.MaPhieuNhap))
    THROW 50010, N'Phieu_NhapHang có phiếu không có chi tiết', 1;

-- Tồn cuối không được lớn hơn tổng nhập (tồn đầu tháng = 0)
IF EXISTS (
    SELECT 1
    FROM dbo.TonKho_ChiNhanh tk
    WHERE tk.SoLuongTon > (SELECT ISNULL(SUM(ct.SoLuong), 0)
                           FROM dbo.ChiTiet_NhapHang ct
                           JOIN dbo.Phieu_NhapHang pn ON pn.MaPhieuNhap = ct.MaPhieuNhap
                           WHERE pn.MaChiNhanh = tk.MaChiNhanh AND ct.MaNguyenLieu = tk.MaNguyenLieu)
)
    THROW 50011, N'TonKho_ChiNhanh lớn hơn tổng nhập tháng 9', 1;

UPDATE pn
SET TongTien = t.TongTien
FROM dbo.Phieu_NhapHang pn
JOIN (SELECT MaPhieuNhap, SUM(ThanhTien) AS TongTien
      FROM dbo.ChiTiet_NhapHang
      GROUP BY MaPhieuNhap) t ON t.MaPhieuNhap = pn.MaPhieuNhap;

UPDATE dbo.Phieu_NhapHang
SET DaThanhToan = CASE TrangThaiCongNo
                      WHEN N'DaTT'       THEN TongTien
                      WHEN N'TraMotPhan' THEN ROUND(TongTien / 2, -3)
                      ELSE 0
                  END;

/*------------------------------------------------------------------------------
  23. PHIẾU ĐIỀU CHUYỂN (6 phiếu = 3 lần mượn hàng giữa chi nhánh + 3 lần trả lại)
      Chi nhánh sắp hết hàng trước ngày NCC giao thì mượn chi nhánh khác,
      nhận hàng NCC xong trả lại đúng số lượng → tồn cuối tháng không đổi
      TrangThai: ChoGui | DangChuyen | DaNhan | DaHuy
------------------------------------------------------------------------------*/
INSERT INTO dbo.Phieu_DieuChuyen (MaKhoGui, MaKhoNhan, NgayGui, NgayNhan, TrangThai, NguoiGui, NguoiNhan)
SELECT gui.MaChiNhanh, nhan.MaChiNhanh, CAST(v.NgayGui AS DATETIME2(0)), CAST(v.NgayNhan AS DATETIME2(0)),
       N'DaNhan', nvg.MaNhanVien, nvn.MaNhanVien
FROM (VALUES
    -- Gửi     Nhận     Ngày gửi            Ngày nhận           Người gửi Người nhận
    (N'CN03', N'CN01', '2026-09-06 14:00', '2026-09-06 14:35', N'NV019', N'NV003'),   -- CN01 hết phô mai, xúc xích (Chủ nhật)
    (N'CN01', N'CN03', '2026-09-09 14:00', '2026-09-09 14:35', N'NV003', N'NV019'),   -- CN01 trả sau đợt giao 08/09
    (N'CN01', N'CN02', '2026-09-13 15:00', '2026-09-13 15:50', N'NV003', N'NV011'),   -- CN02 sắp hết ly, nắp
    (N'CN02', N'CN01', '2026-09-16 15:00', '2026-09-16 15:50', N'NV011', N'NV003'),   -- CN02 trả sau đợt giao 15/09
    (N'CN01', N'CN02', '2026-09-20 17:00', '2026-09-20 17:50', N'NV004', N'NV012'),   -- CN02 sắp hết bò Úc
    (N'CN02', N'CN01', '2026-09-23 17:00', '2026-09-23 17:50', N'NV012', N'NV004')    -- CN02 trả sau đợt giao 22/09
) AS v (KhoGui, KhoNhan, NgayGui, NgayNhan, NguoiGui, NguoiNhan)
JOIN dbo.ChiNhanh gui  ON gui.MaCode  = v.KhoGui
JOIN dbo.ChiNhanh nhan ON nhan.MaCode = v.KhoNhan
JOIN dbo.NhanVien nvg  ON nvg.MaCode  = v.NguoiGui
JOIN dbo.NhanVien nvn  ON nvn.MaCode  = v.NguoiNhan;

INSERT INTO dbo.ChiTiet_DieuChuyen (MaPhieu, MaNguyenLieu, SoLuongGui, SoLuongNhanThucTe)
SELECT dc.MaPhieu, nl.MaNguyenLieu, v.SoLuong, v.SoLuong
FROM (VALUES
    ('2026-09-06 14:00', N'Phô mai Mozzarella',                   200),
    ('2026-09-06 14:00', N'Xúc xích Đức',                           5),
    ('2026-09-09 14:00', N'Phô mai Mozzarella',                   200),
    ('2026-09-09 14:00', N'Xúc xích Đức',                           5),
    ('2026-09-13 15:00', N'Ly nhựa PET 500ml',                     30),
    ('2026-09-13 15:00', N'Nắp ly cầu',                            30),
    ('2026-09-16 15:00', N'Ly nhựa PET 500ml',                     30),
    ('2026-09-16 15:00', N'Nắp ly cầu',                            30),
    ('2026-09-20 17:00', N'Thịt bò Úc (thăn)',                    150),
    ('2026-09-23 17:00', N'Thịt bò Úc (thăn)',                    150)
) AS v (NgayGui, TenNL, SoLuong)
JOIN dbo.Phieu_DieuChuyen dc ON dc.NgayGui = CAST(v.NgayGui AS DATETIME2(0))
JOIN dbo.NguyenLieu nl       ON nl.TenNguyenLieu = v.TenNL;

IF (SELECT COUNT(*) FROM dbo.Phieu_DieuChuyen) <> 6 OR (SELECT COUNT(*) FROM dbo.ChiTiet_DieuChuyen) <> 10
    THROW 50012, N'Điều chuyển thiếu dòng: mã chi nhánh / nhân viên / tên NL gõ sai', 1;

-- Mượn bao nhiêu trả bấy nhiêu: mỗi chi nhánh, mỗi NL tổng chuyển đi = tổng chuyển đến
IF EXISTS (
    SELECT 1
    FROM (SELECT dc.MaKhoGui AS MaChiNhanh, ct.MaNguyenLieu, -ct.SoLuongGui AS SL
          FROM dbo.ChiTiet_DieuChuyen ct JOIN dbo.Phieu_DieuChuyen dc ON dc.MaPhieu = ct.MaPhieu
          UNION ALL
          SELECT dc.MaKhoNhan, ct.MaNguyenLieu, ct.SoLuongNhanThucTe
          FROM dbo.ChiTiet_DieuChuyen ct JOIN dbo.Phieu_DieuChuyen dc ON dc.MaPhieu = ct.MaPhieu) x
    GROUP BY MaChiNhanh, MaNguyenLieu
    HAVING SUM(SL) <> 0
)
    THROW 50013, N'Điều chuyển không cân: có chi nhánh mượn chưa trả đủ', 1;

/*------------------------------------------------------------------------------
  24. PHIẾU HỦY HAO HỤT (3 phiếu / chi nhánh = 9 phiếu, lập cuối ca tối)
      Hao hụt tháng 9 (mục 21) = hủy ở đây + chênh lệch kiểm kê (mục 25)
      TrangThai: Draft | DaDuyet | TuChoi
------------------------------------------------------------------------------*/
