        DiemCong, DiemTru, TTDon, TTThanhToan, NgayTao, NgayTT)
JOIN dbo.ChiNhanh    cn ON cn.MaCode  = v.MaCN
JOIN dbo.NhanVien    nv ON nv.MaCode  = v.MaNV
JOIN dbo.NhatKy_CaLam ca ON ca.MaChiNhanh = cn.MaChiNhanh
                       AND CAST(v.NgayTao AS DATETIME2(0)) >= ca.GioMo
                       AND CAST(v.NgayTao AS DATETIME2(0)) <  ca.GioDong
LEFT JOIN dbo.KhachHang kh ON kh.SoDienThoai = v.SDT
LEFT JOIN dbo.KhuyenMai km ON km.MaCode      = v.MaKM;

