JOIN dbo.HoaDon    hd ON hd.MaDonLocal  = v.MaDon
JOIN dbo.KhachHang kh ON kh.SoDienThoai = v.SDT;

IF (SELECT COUNT(*) FROM dbo.GiaoDich_TichDiem) <> 719
    THROW 50107, N'GiaoDich_TichDiem thiếu dòng', 1;

-- Điểm hiện tại của khách = tổng các giao dịch điểm
IF EXISTS (SELECT 1 FROM dbo.KhachHang kh
           WHERE kh.DiemHienTai <> ISNULL((SELECT SUM(g.SoDiemThayDoi) FROM dbo.GiaoDich_TichDiem g
                                           WHERE g.MaKhachHang = kh.MaKhachHang), 0))
    THROW 50108, N'KhachHang.DiemHienTai không khớp GiaoDich_TichDiem', 1;

-- Tiền mặt thu trong ca = TienHeThong - TienDauCa
IF EXISTS (SELECT 1 FROM dbo.NhatKy_CaLam ca
           WHERE ca.TienHeThong - ca.TienDauCa <> ISNULL((
                 SELECT SUM(t.SoTien) FROM dbo.ThanhToan_HoaDon t JOIN dbo.HoaDon hd ON hd.MaHoaDon = t.MaHoaDon
                 WHERE hd.MaCa = ca.MaCa AND t.HinhThuc = N'TienMat'), 0))
    THROW 50109, N'NhatKy_CaLam: tiền hệ thống không khớp tiền mặt thu trong ca', 1;

-- Nhập - xuất bán (qua công thức, combo tách thành món) - tồn kho 30/09 = hao hụt, không được âm
IF EXISTS (
    SELECT 1
    FROM dbo.TonKho_ChiNhanh tk
    WHERE (SELECT ISNULL(SUM(ct.SoLuong), 0) FROM dbo.ChiTiet_NhapHang ct
           JOIN dbo.Phieu_NhapHang pn ON pn.MaPhieuNhap = ct.MaPhieuNhap
           WHERE pn.MaChiNhanh = tk.MaChiNhanh AND ct.MaNguyenLieu = tk.MaNguyenLieu)
        - (SELECT ISNULL(SUM(x.SoLuong * c.SoLuongTrenMotPhan), 0)
           FROM (SELECT hd.MaChiNhanh, ISNULL(cb.MaSanPham, ct.MaSanPham) AS MaSanPham,
                        ct.SoLuong * ISNULL(cb.SoLuong, 1) AS SoLuong
                 FROM dbo.ChiTiet_HoaDon ct
                 JOIN dbo.HoaDon hd ON hd.MaHoaDon = ct.MaHoaDon AND hd.TrangThaiDon = N'HoanThanh'
                 LEFT JOIN dbo.Combo_ChiTiet cb ON cb.MaCombo = ct.MaSanPham) x
           JOIN dbo.CongThuc c ON c.MaSanPham = x.MaSanPham
           WHERE x.MaChiNhanh = tk.MaChiNhanh AND c.MaNguyenLieu = tk.MaNguyenLieu)
        - tk.SoLuongTon < 0
)
    THROW 50110, N'Kho âm: xuất bán + tồn cuối lớn hơn tổng nhập', 1;
-- <<< KẾT THÚC NHÓM 6 >>>

/*------------------------------------------------------------------------------
  31. NHẬT KÝ KHO (NHÓM 7) - mỗi dòng = 1 lần tồn 1 nguyên liệu tại 1 chi nhánh thay đổi
      NHAP        + phiếu nhập NCC (hàng giao 05:30 sáng ngày nhận)  → PHIEU_NHAP
      XUAT_BAN    − hóa đơn hoàn thành, trừ theo công thức
                    (combo trừ theo công thức từng món thành phần)    → HOADON
      CHUYEN_DI   − phiếu điều chuyển, kho gửi (lúc gửi)             → DIEU_CHUYEN
      CHUYEN_DEN  + phiếu điều chuyển, kho nhận (lúc nhận)           → DIEU_CHUYEN
      HUY         − phiếu hủy hao hụt                                → HUY
      KIEM_KE     ± chênh lệch kiểm kho (bỏ dòng chênh lệch = 0)     → KIEM_KHO
      Hóa đơn đã hủy không trừ kho → không có nhật ký
      TonSau = tồn sau giao dịch (tồn đầu tháng = 0), dòng cuối mỗi NL = TonKho_ChiNhanh
      Nhật ký là dữ liệu dẫn xuất từ các mục trên nên chèn bằng INSERT ... SELECT
------------------------------------------------------------------------------*/
WITH GiaoDich AS (
    -- Nhập hàng: quản lý chi nhánh nhận hàng
    SELECT pn.MaChiNhanh, ct.MaNguyenLieu, N'NHAP' AS LoaiGiaoDich, 1 AS ThuTu,
           ct.SoLuong AS SoLuongThayDoi, ql.MaNhanVien,
           DATEADD(MINUTE, 330, CAST(pn.NgayNhan AS DATETIME2(0))) AS NgayTao,
           N'PHIEU_NHAP' AS LoaiThamChieu, pn.MaPhieuNhap AS MaThamChieu,
           CAST(N'Nhập từ ' + ncc.TenNCC AS NVARCHAR(255)) AS GhiChu
    FROM dbo.ChiTiet_NhapHang ct
    JOIN dbo.Phieu_NhapHang pn ON pn.MaPhieuNhap = ct.MaPhieuNhap
    JOIN dbo.NhaCungCap ncc    ON ncc.MaNCC = pn.MaNCC
    JOIN dbo.NhanVien ql       ON ql.MaChiNhanh = pn.MaChiNhanh AND ql.ChucVu = N'Quản lý'

    UNION ALL
    -- Bán hàng: gộp theo hóa đơn + nguyên liệu, người trừ kho = thu ngân
    SELECT h.MaChiNhanh, ct.MaNguyenLieu, N'XUAT_BAN', 3,
           -SUM(d.SoLuong * ISNULL(cb.SoLuong, 1) * ct.SoLuongTrenMotPhan), h.MaThuNgan,
           h.NgayTao, N'HOADON', h.MaHoaDon, h.MaDonLocal
    FROM dbo.HoaDon h
    JOIN dbo.ChiTiet_HoaDon d      ON d.MaHoaDon = h.MaHoaDon
    LEFT JOIN dbo.Combo_ChiTiet cb ON cb.MaCombo = d.MaSanPham
    JOIN dbo.CongThuc ct           ON ct.MaSanPham = ISNULL(cb.MaSanPham, d.MaSanPham)
    WHERE h.TrangThaiDon = N'HoanThanh'
    GROUP BY h.MaChiNhanh, ct.MaNguyenLieu, h.MaThuNgan, h.NgayTao, h.MaHoaDon, h.MaDonLocal

    UNION ALL
    SELECT dc.MaKhoGui, ct.MaNguyenLieu, N'CHUYEN_DI', 4,
           -ct.SoLuongGui, dc.NguoiGui, dc.NgayGui, N'DIEU_CHUYEN', dc.MaPhieu,
           N'Chuyển sang ' + nhan.MaCode + N' - ' + nhan.TenChiNhanh
    FROM dbo.ChiTiet_DieuChuyen ct
    JOIN dbo.Phieu_DieuChuyen dc ON dc.MaPhieu = ct.MaPhieu
    JOIN dbo.ChiNhanh nhan       ON nhan.MaChiNhanh = dc.MaKhoNhan

    UNION ALL
    SELECT dc.MaKhoNhan, ct.MaNguyenLieu, N'CHUYEN_DEN', 2,
           ct.SoLuongNhanThucTe, dc.NguoiNhan, dc.NgayNhan, N'DIEU_CHUYEN', dc.MaPhieu,
           N'Nhận từ ' + gui.MaCode + N' - ' + gui.TenChiNhanh
    FROM dbo.ChiTiet_DieuChuyen ct
    JOIN dbo.Phieu_DieuChuyen dc ON dc.MaPhieu = ct.MaPhieu
    JOIN dbo.ChiNhanh gui        ON gui.MaChiNhanh = dc.MaKhoGui
    WHERE dc.TrangThai = N'DaNhan'

    UNION ALL
    SELECT ph.MaChiNhanh, ct.MaNguyenLieu, N'HUY', 5,
           -ct.SoLuong, ph.NguoiLap, ph.NgayLap, N'HUY', ph.MaPhieu, ct.GhiChu
    FROM dbo.ChiTiet_HuyHaoHut ct
    JOIN dbo.Phieu_HuyHaoHut ph ON ph.MaPhieu = ct.MaPhieu
    WHERE ph.TrangThai = N'DaDuyet'

    UNION ALL
    SELECT kk.MaChiNhanh, ct.MaNguyenLieu, N'KIEM_KE', 6,
           ct.ChenhLech, kk.NguoiKiem, kk.NgayKiem, N'KIEM_KHO', kk.MaPhieu,
           N'Hệ thống ' + FORMAT(ct.SoLuongHeThong, '0.###') + N', thực tế ' + FORMAT(ct.SoLuongThucTe, '0.###')
    FROM dbo.ChiTiet_KiemKho ct
    JOIN dbo.Phieu_KiemKho kk ON kk.MaPhieu = ct.MaPhieu
    WHERE kk.TrangThai = N'HoanThanh' AND ct.ChenhLech <> 0
)
INSERT INTO dbo.NhatKy_Kho (MaChiNhanh, MaNguyenLieu, LoaiGiaoDich, SoLuongThayDoi, TonSau,
                            MaNhanVien, NgayTao, LoaiThamChieu, MaThamChieu, GhiChu)
SELECT gd.MaChiNhanh, gd.MaNguyenLieu, gd.LoaiGiaoDich, gd.SoLuongThayDoi,
       SUM(gd.SoLuongThayDoi) OVER (PARTITION BY gd.MaChiNhanh, gd.MaNguyenLieu
                                    ORDER BY gd.NgayTao, gd.ThuTu, gd.MaThamChieu
                                    ROWS UNBOUNDED PRECEDING),
       gd.MaNhanVien, gd.NgayTao, gd.LoaiThamChieu, gd.MaThamChieu, gd.GhiChu
FROM GiaoDich gd
ORDER BY gd.NgayTao, gd.ThuTu, gd.MaThamChieu, gd.MaChiNhanh, gd.MaNguyenLieu;

-- Số dòng khớp với chứng từ gốc
IF (SELECT COUNT(*) FROM dbo.NhatKy_Kho WHERE LoaiGiaoDich = N'NHAP') <> (SELECT COUNT(*) FROM dbo.ChiTiet_NhapHang)
   OR (SELECT COUNT(*) FROM dbo.NhatKy_Kho WHERE LoaiGiaoDich = N'HUY') <> (SELECT COUNT(*) FROM dbo.ChiTiet_HuyHaoHut)
   OR (SELECT COUNT(*) FROM dbo.NhatKy_Kho WHERE LoaiGiaoDich IN (N'CHUYEN_DI', N'CHUYEN_DEN')) <> 2 * (SELECT COUNT(*) FROM dbo.ChiTiet_DieuChuyen)
   OR (SELECT COUNT(*) FROM dbo.NhatKy_Kho WHERE LoaiGiaoDich = N'KIEM_KE') <> (SELECT COUNT(*) FROM dbo.ChiTiet_KiemKho WHERE ChenhLech <> 0)
    THROW 50201, N'NhatKy_Kho thiếu dòng so với phiếu nhập / hủy / điều chuyển / kiểm kho', 1;

-- Không lúc nào tồn âm
IF EXISTS (SELECT 1 FROM dbo.NhatKy_Kho WHERE TonSau < 0)
    THROW 50202, N'NhatKy_Kho có thời điểm tồn âm', 1;

-- Kiểm kho: số hệ thống = tồn ngay trước lúc kiểm
IF EXISTS (
    SELECT 1
    FROM dbo.ChiTiet_KiemKho ct
    JOIN dbo.Phieu_KiemKho kk ON kk.MaPhieu = ct.MaPhieu
    WHERE ct.SoLuongHeThong <> ISNULL((SELECT TOP 1 nk.TonSau FROM dbo.NhatKy_Kho nk
                                       WHERE nk.MaChiNhanh = kk.MaChiNhanh AND nk.MaNguyenLieu = ct.MaNguyenLieu
                                         AND nk.NgayTao <= kk.NgayKiem AND nk.LoaiGiaoDich <> N'KIEM_KE'
                                       ORDER BY nk.MaNhatKy DESC), 0)
)
    THROW 50203, N'Số hệ thống trên phiếu kiểm kho lệch nhật ký kho', 1;

-- Tồn sau giao dịch cuối cùng = tồn kho chốt 30/09
IF EXISTS (
    SELECT 1
    FROM dbo.TonKho_ChiNhanh tk
    WHERE tk.SoLuongTon <> ISNULL((SELECT TOP 1 nk.TonSau FROM dbo.NhatKy_Kho nk
                                   WHERE nk.MaChiNhanh = tk.MaChiNhanh AND nk.MaNguyenLieu = tk.MaNguyenLieu
                                   ORDER BY nk.MaNhatKy DESC), 0)
)
    THROW 50204, N'Tồn cuối trong NhatKy_Kho lệch TonKho_ChiNhanh', 1;

COMMIT TRANSACTION;
GO

/*------------------------------------------------------------------------------
  KIỂM TRA NHANH
  Kỳ vọng: VaiTro 3 | MenuChucNang 35 | ChiNhanh 3 | NhanVien 25 | TaiKhoan 25 | NhatKy_CaLam 270
           ThietBi 47 | NhaCungCap 13 | DonVi 10 | QuyDoi_DonVi 2 | DanhMuc 9 | SanPham 46
           SanPham_ChiNhanh 138 | NguyenLieu 60 | CongThuc 269 | TonKho_ChiNhanh 180
           Combo_ChiTiet 12 | KhuyenMai 5 | CauHinh_HangThanhVien 3 | KhachHang 39
           Phieu_NhapHang 132 | ChiTiet_NhapHang 546
           Phieu_DieuChuyen 6 | ChiTiet_DieuChuyen 10 | Phieu_HuyHaoHut 9 | ChiTiet_HuyHaoHut 81
           Phieu_KiemKho 6 | ChiTiet_KiemKho 75
           HoaDon 3785 | ChiTiet_HoaDon 7260 | ThanhToan_HoaDon 3796 | NhatKy_GiaoHang 886 | GiaoDich_TichDiem 719
           VaiTro_Menu: ADMIN 35 | MANAGER 34 | STAFF 15
------------------------------------------------------------------------------*/
SELECT N'VaiTro' AS Bang, COUNT(*) AS SoDong FROM dbo.VaiTro
UNION ALL SELECT N'MenuChucNang', COUNT(*) FROM dbo.MenuChucNang
UNION ALL SELECT N'VaiTro_Menu',  COUNT(*) FROM dbo.VaiTro_Menu
UNION ALL SELECT N'ChiNhanh',     COUNT(*) FROM dbo.ChiNhanh
UNION ALL SELECT N'NhanVien',     COUNT(*) FROM dbo.NhanVien
UNION ALL SELECT N'TaiKhoan',     COUNT(*) FROM dbo.TaiKhoan
UNION ALL SELECT N'NhatKy_CaLam', COUNT(*) FROM dbo.NhatKy_CaLam
UNION ALL SELECT N'ThietBi',      COUNT(*) FROM dbo.ThietBi
UNION ALL SELECT N'NhaCungCap',       COUNT(*) FROM dbo.NhaCungCap
UNION ALL SELECT N'DonVi',            COUNT(*) FROM dbo.DonVi
UNION ALL SELECT N'QuyDoi_DonVi',     COUNT(*) FROM dbo.QuyDoi_DonVi
UNION ALL SELECT N'DanhMuc',          COUNT(*) FROM dbo.DanhMuc
UNION ALL SELECT N'SanPham',          COUNT(*) FROM dbo.SanPham
UNION ALL SELECT N'SanPham_ChiNhanh', COUNT(*) FROM dbo.SanPham_ChiNhanh
UNION ALL SELECT N'NguyenLieu',       COUNT(*) FROM dbo.NguyenLieu
UNION ALL SELECT N'CongThuc',         COUNT(*) FROM dbo.CongThuc
UNION ALL SELECT N'TonKho_ChiNhanh',  COUNT(*) FROM dbo.TonKho_ChiNhanh
UNION ALL SELECT N'Combo_ChiTiet',    COUNT(*) FROM dbo.Combo_ChiTiet
UNION ALL SELECT N'KhuyenMai',        COUNT(*) FROM dbo.KhuyenMai
UNION ALL SELECT N'CauHinh_HangThanhVien', COUNT(*) FROM dbo.CauHinh_HangThanhVien
UNION ALL SELECT N'KhachHang',        COUNT(*) FROM dbo.KhachHang
UNION ALL SELECT N'Phieu_NhapHang',   COUNT(*) FROM dbo.Phieu_NhapHang
UNION ALL SELECT N'ChiTiet_NhapHang', COUNT(*) FROM dbo.ChiTiet_NhapHang
UNION ALL SELECT N'Phieu_DieuChuyen',   COUNT(*) FROM dbo.Phieu_DieuChuyen
UNION ALL SELECT N'ChiTiet_DieuChuyen', COUNT(*) FROM dbo.ChiTiet_DieuChuyen
UNION ALL SELECT N'Phieu_HuyHaoHut',    COUNT(*) FROM dbo.Phieu_HuyHaoHut
UNION ALL SELECT N'ChiTiet_HuyHaoHut',  COUNT(*) FROM dbo.ChiTiet_HuyHaoHut
UNION ALL SELECT N'Phieu_KiemKho',      COUNT(*) FROM dbo.Phieu_KiemKho
UNION ALL SELECT N'ChiTiet_KiemKho',    COUNT(*) FROM dbo.ChiTiet_KiemKho
UNION ALL SELECT N'HoaDon',             COUNT(*) FROM dbo.HoaDon
UNION ALL SELECT N'ChiTiet_HoaDon',     COUNT(*) FROM dbo.ChiTiet_HoaDon
UNION ALL SELECT N'ThanhToan_HoaDon',   COUNT(*) FROM dbo.ThanhToan_HoaDon
UNION ALL SELECT N'NhatKy_GiaoHang',    COUNT(*) FROM dbo.NhatKy_GiaoHang
UNION ALL SELECT N'GiaoDich_TichDiem',  COUNT(*) FROM dbo.GiaoDich_TichDiem
UNION ALL SELECT N'NhatKy_Kho',         COUNT(*) FROM dbo.NhatKy_Kho;

-- Doanh thu tháng 9 theo chi nhánh (đơn hoàn thành, không tính phí ship)
SELECT cn.MaCode, COUNT(*) AS SoHoaDon,
       SUM(hd.TongTienHang) AS TienHang, SUM(hd.TienGiam) AS TienGiam,
       SUM(hd.TongThanhToan - hd.PhiShip) AS DoanhThu, SUM(hd.TongThanhToan - hd.PhiShip) / 30 AS TB_Ngay
FROM dbo.HoaDon hd
JOIN dbo.ChiNhanh cn ON cn.MaChiNhanh = hd.MaChiNhanh
WHERE hd.TrangThaiDon = N'HoanThanh'
GROUP BY cn.MaCode;

-- Số lần dùng từng mã khuyến mãi
SELECT km.MaCode, COUNT(hd.MaHoaDon) AS SoDon
FROM dbo.KhuyenMai km
LEFT JOIN dbo.HoaDon hd ON hd.MaKhuyenMai = km.MaKhuyenMai
GROUP BY km.MaCode;

-- Nhật ký kho theo chi nhánh và loại giao dịch
SELECT cn.MaCode, nk.LoaiGiaoDich, COUNT(*) AS SoDong, SUM(nk.SoLuongThayDoi) AS TongThayDoi
FROM dbo.NhatKy_Kho nk
JOIN dbo.ChiNhanh cn ON cn.MaChiNhanh = nk.MaChiNhanh
GROUP BY cn.MaCode, nk.LoaiGiaoDich
ORDER BY cn.MaCode, nk.LoaiGiaoDich;

-- Ví dụ thẻ kho: Heo quay tại CN02 (bỏ các dòng bán cho gọn)
SELECT nk.NgayTao, nk.LoaiGiaoDich, nk.SoLuongThayDoi, nk.TonSau, nv.MaCode AS NhanVien, nk.GhiChu
FROM dbo.NhatKy_Kho nk
JOIN dbo.ChiNhanh cn   ON cn.MaChiNhanh = nk.MaChiNhanh
JOIN dbo.NguyenLieu nl ON nl.MaNguyenLieu = nk.MaNguyenLieu
LEFT JOIN dbo.NhanVien nv ON nv.MaNhanVien = nk.MaNhanVien
WHERE cn.MaCode = N'CN02' AND nl.TenNguyenLieu = N'Heo quay' AND nk.LoaiGiaoDich <> N'XUAT_BAN'
ORDER BY nk.MaNhatKy;

-- Hao hụt tháng 9 theo chi nhánh: hủy (mục 24) + chênh lệch kiểm kê (mục 25)
SELECT cn.MaCode,
       (SELECT COUNT(*) FROM dbo.Phieu_HuyHaoHut ph WHERE ph.MaChiNhanh = cn.MaChiNhanh) AS PhieuHuy,
       (SELECT COUNT(*) FROM dbo.Phieu_KiemKho kk WHERE kk.MaChiNhanh = cn.MaChiNhanh) AS PhieuKiem,
       (SELECT COUNT(*) FROM dbo.Phieu_DieuChuyen dc WHERE dc.MaKhoGui = cn.MaChiNhanh) AS PhieuChuyenDi,
       (SELECT COUNT(*) FROM dbo.Phieu_DieuChuyen dc WHERE dc.MaKhoNhan = cn.MaChiNhanh) AS PhieuChuyenDen
FROM dbo.ChiNhanh cn;

-- Tiền nhập hàng tháng 9 theo chi nhánh
SELECT cn.MaCode, COUNT(*) AS SoPhieu, SUM(pn.TongTien) AS TongTienNhap,
       SUM(pn.DaThanhToan) AS DaTra, SUM(pn.TongTien - pn.DaThanhToan) AS ConNo
FROM dbo.Phieu_NhapHang pn
JOIN dbo.ChiNhanh cn ON cn.MaChiNhanh = pn.MaChiNhanh
GROUP BY cn.MaCode;

SELECT vt.MaCode AS VaiTro, COUNT(*) AS SoMenu
FROM dbo.VaiTro_Menu vm
JOIN dbo.VaiTro vt ON vt.MaVaiTro = vm.MaVaiTro
GROUP BY vt.MaCode;
GO
